from taf.gnb.oam.coam.admin.schemas.procedure.ccm_uplink import CCMUplink


class CCMUplinkPucch(CCMUplink):
    def __init__(self, nrcell_rdn, nrarfcn_ul, reporting_time_interval, beam_pattern_id, performance_test_type,
                 receiving_slot, expectation_slot, pucch_format, ru_mode, phys_cell_id, format_0_sym_num=None,
                 format_2_test_type=None):
        super(CCMUplinkPucch, self).__init__(nrcell_rdn=nrcell_rdn,
                                             nrarfcn_ul=nrarfcn_ul,
                                             reporting_time_interval=reporting_time_interval,
                                             beam_pattern_id=beam_pattern_id,
                                             performance_test_type=performance_test_type,
                                             ru_mode=ru_mode,
                                             phys_cell_id=phys_cell_id)
        self.pucch_params = {"receivingSlot": self.validate_param('receivingSlot',
                                                                  receiving_slot,
                                                                  (0 <= receiving_slot <= 1023)),
                             "expectationSlot": self.validate_param('expectationSlot',
                                                                    expectation_slot,
                                                                    (0 <= expectation_slot <= 1023)),
                             "pucchFormat": self.validate_param('pucchFormat',
                                                                pucch_format,
                                                                (pucch_format in ("F0", "F2"))),
                             "format0SymNum": self.validate_param('format0SymNum',
                                                                  format_0_sym_num,
                                                                  (format_0_sym_num is None
                                                                   or (1 <= format_0_sym_num <= 2))
                                                                  ),
                             "format2TestType": self.validate_param('format2TestType',
                                                                    format_2_test_type,
                                                                    (format_2_test_type is None
                                                                     or format_2_test_type in ("Ack", "Uci"))
                                                                    )}

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_pucch_param(parameter):
            return response_dict['params']['pucchParams'][parameter]

        def _get_optional_param(test_type, parameter):
            test_type_dict = response_dict['params'][test_type]
            return test_type_dict.get(parameter)

        nrcell_rdn = response_dict['nrcell_rDN']
        nrarfcn_ul = response_dict['params']['nrarfcnUl'] if 'nrarfcnUl' in response_dict['params'] else None
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        beam_pattern_id = response_dict['params']['beamPatternId']
        performance_test_type = response_dict['params']['performanceTestType']
        ru_mode = response_dict['params']['ruMode']
        phys_cell_id = response_dict['params']['physCellId']
        pucch_params = {"receivingSlot": _get_pucch_param('receivingSlot'),
                        "expectationSlot": _get_pucch_param('expectationSlot'),
                        "pucchFormat": _get_pucch_param('pucchFormat'),
                        "format0SymNum": _get_optional_param('pucchParams', 'format0SymNum'),
                        "format2TestType": _get_optional_param('pucchParams', 'format2TestType')}

        return cls(nrcell_rdn=nrcell_rdn,
                   nrarfcn_ul=nrarfcn_ul,
                   reporting_time_interval=reporting_time_interval,
                   beam_pattern_id=beam_pattern_id,
                   performance_test_type=performance_test_type,
                   ru_mode=ru_mode,
                   phys_cell_id=phys_cell_id,
                   receiving_slot=pucch_params['receivingSlot'],
                   expectation_slot=pucch_params['expectationSlot'],
                   pucch_format=pucch_params['pucchFormat'],
                   format_0_sym_num=pucch_params['format0SymNum'],
                   format_2_test_type=pucch_params['format2TestType'])

    def as_dict(self):
        attributes = super(CCMUplinkPucch, self).as_dict()

        self.pucch_params = self._remove_empty_params(self.pucch_params)
        attributes['params']['pucchParams'] = self.pucch_params

        return attributes

    @staticmethod
    def _remove_empty_params(params):
        return {k: v for k, v in params.items() if v is not None}
